'use strict';
window.ResearchUI=(()=>{
 const d=window.HERB_DATA,c=window.CORPUS_DATA,m=window.METHODOLOGY_DATA,Q=window.QuantModel;
 const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const H=id=>d.herbs.find(h=>h.id===id),F=id=>d.formulas.find(f=>f.id===id);
 const link=(url,label)=>/^https:\/\//.test(url||'')?`<a class="small-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
 const sourceLink=(id,label='原文來源')=>{const s=d.sources.find(s=>s.id===id);return s?link(s.url,label):'來源未錄'};
 const pct=x=>(x*100).toFixed(0)+'%', number=x=>Number(x.toFixed(2)).toString();
 const range=x=>x?x[0]===x[1]?number(x[0]):number(x[0])+' ～ '+number(x[1]):'未知';
 const reviewed=h=>h.reviewStatus==='curated_source_excerpt_reviewed';
 const badge=h=>`<span class="review-tag ${reviewed(h)?'reviewed':''}">${reviewed(h)?'節錄已核':'自動擷取・待核'}</span>`;
 const downloads=()=>`<div class="download-bar"><span>保留來源與未知值的研究資料</span><a class="button secondary" href="downloads/tcm-research-library.zip" download>下載完整研究包</a><a class="small-link" href="downloads/herbs.csv" download>草藥 CSV</a><a class="small-link" href="downloads/research-manifest.json" download>範圍與未完成項目</a></div>`;
 const stats=()=>`<div class="research-stats"><div><b>1,362</b><span>目錄條目／來源版本</span></div><div><b>14</b><span>完整來源轉錄</span></div><div><b>340</b><span>古籍本草條目</span></div><div><b>18</b><span>經方校核基準</span></div></div>`;
 let context,active,corpusQuery='',category='',corpusStatus='',corpusPage=0,quantQuery='',quantPage=0,quantReview='',quantOptions={scheme:'base',mild:.5,strong:1.5};
 let benchmarkId='sijunzi',pairA='rensen',pairB='baizhu',discoveryResult=null,textResults='',textBusy=false,textRun=0;
 const cache=new Map();
 function render(view,ctx){context=ctx;active=view;const p=document.querySelector('#view-content');if(view==='corpus')p.innerHTML=corpusHTML();if(view==='frameworks')p.innerHTML=frameworkHTML();if(view==='quant')p.innerHTML=quantHTML();if(view==='benchmark'){const ids=[...new Set(d.formulas.flatMap(f=>f.herbIds))];if(!ids.includes(pairA))pairA=ids[0];if(!ids.includes(pairB)||pairA===pairB)pairB=ids.find(x=>x!==pairA);p.innerHTML=benchmarkHTML()}if(view==='discovery')p.innerHTML=discoveryHTML()}
 function matchingBooks(){const q=corpusQuery.trim().toLocaleLowerCase();return c.books.filter(b=>(!category||b.category===category)&&(!corpusStatus||b.status===corpusStatus)&&(!q||[b.title,b.sourceDisplayTitle,b.author,b.era,b.edition].join(' ').toLocaleLowerCase().includes(q)))}
 function bookRows(){const found=matchingBooks(),page=found.slice(corpusPage*30,(corpusPage+1)*30);return `<div class="table-scroll"><table class="research-table"><thead><tr><th>典籍／版本</th><th>作者・年代</th><th>版本線索</th><th>取得狀態</th></tr></thead><tbody>${page.map(b=>`<tr><td>${link(b.url,b.title)}<small>${esc(b.category)}</small>${b.sourceDisplayTitle&&b.sourceDisplayTitle!==b.title?`<small>源頁題名：${esc(b.sourceDisplayTitle)}；身份待逐本考證</small>`:''}</td><td>${esc(b.author||'未錄')}<small>${esc(b.era||'未錄')}</small></td><td>${esc(b.edition||'底本資訊未錄')}</td><td><span class="review-tag ${b.status==='fulltext'?'reviewed':''}">${b.status==='fulltext'?'全文已取得':'僅書目'}</span>${b.status==='fulltext'?`<small>${b.characters.toLocaleString()} 字符</small>`:''}</td></tr>`).join('')}</tbody></table></div>${pager('corpus',corpusPage,found.length,30)}<p class="rule-note">所有源頁已核對可存取及頁首書目；完整取得、逐字校勘、結構化標註與模型學習是不同狀態。未將書目條目算成已學習全文。</p>`}
 function pager(type,page,count,size){return `<div class="pager"><span>${count.toLocaleString()} 條結果・第 ${page+1} / ${Math.max(1,Math.ceil(count/size))} 頁</span><button class="button secondary" data-research-page="${type}" data-delta="-1" ${page===0?'disabled':''}>上一頁</button><button class="button secondary" data-research-page="${type}" data-delta="1" ${(page+1)*size>=count?'disabled':''}>下一頁</button></div>`}
 function corpusHTML(){const cores=c.books.filter(b=>b.status==='fulltext');return stats()+`<div class="notice">本次以中醫笈成可公開存取目錄為主，補查維基文庫及官方館藏。1,362 為版本／目錄條目，並非 1,362 部獨立著作；尚未涵蓋全球館藏與所有原刻本。125 個源頁題名差異已保留待考證。 ${link('https://jicheng.tw/tcm/book/index.html','來源目錄')}</div><section class="panel research-panel"><div class="panel-heading"><h2>典籍目錄</h2><small>書目檢索與版本追蹤</small></div><div class="research-controls"><input class="search" id="corpus-query" aria-label="搜尋典籍目錄" placeholder="典籍、作者、年代或版本" value="${esc(corpusQuery)}"><select id="corpus-category" aria-label="典籍類別"><option value="">全部類別</option>${[...new Set(c.books.map(b=>b.category))].map(x=>`<option ${category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="corpus-status" aria-label="典籍取得狀態"><option value="">全部狀態</option><option value="fulltext" ${corpusStatus==='fulltext'?'selected':''}>全文已取得</option><option value="catalogued" ${corpusStatus==='catalogued'?'selected':''}>僅書目</option></select></div><div id="book-rows">${bookRows()}</div></section><section class="panel research-panel"><div class="panel-heading"><h2>14 個核心來源・全文检索</h2><small>按需載入完整轉錄</small></div><div class="research-controls"><select id="text-book" aria-label="全文範圍"><option value="all">全部 14 個來源</option>${cores.map(b=>`<option value="${b.id}">${esc(b.title)}</option>`).join('')}</select><input class="search" id="text-query" aria-label="全文搜尋詞" placeholder="至少兩字，例如：寒熱、相反"><button class="button primary" id="search-fulltext" ${textBusy?'disabled':''}>${textBusy?'檢索中…':'搜尋全文'}</button></div><div id="fulltext-results">${textResults||'<p class="rule-note">涵蓋《素問》《靈樞》《難經》《傷寒論》《金匱要略》《神農本草經》《本草綱目》《本草備要》《脈經》《景岳全書》《丹溪心法》《小兒藥證直訣》《太平惠民和劑局方》《溫病條辨》。轉錄的字形與其他版本可能不同。</p>'}</div></section>`+downloads()}
 async function searchText(){const input=document.querySelector('#text-query'),q=input.value.trim(),id=document.querySelector('#text-book').value;if(q.length<2){context.notify('全文檢索請至少輸入兩個字');return}const run=++textRun;textBusy=true;const button=document.querySelector('#search-fulltext');button.disabled=true;button.textContent='檢索中…';const books=c.books.filter(b=>b.status==='fulltext'&&(id==='all'||id===b.id));let total=0;const results=[];try{for(const b of books){if(!cache.has(b.id)){const response=await fetch(b.textAsset);if(!response.ok)throw new Error('全文載入失敗');cache.set(b.id,await response.json())}const asset=cache.get(b.id);let at=0,count=0,snippets=[];while((at=asset.text.indexOf(q,at))!==-1){count++;if(snippets.length<8){const start=Math.max(0,at-45),end=Math.min(asset.text.length,at+q.length+85);snippets.push(`<p class="text-hit">${esc(asset.text.slice(start,at))}<mark>${esc(q)}</mark>${esc(asset.text.slice(at+q.length,end))}</p>`)}at+=q.length}total+=count;if(count)results.push(`<article class="text-result"><h3>${esc(b.title)} <small>${count} 處</small></h3><p class="table-note">${esc(b.edition||'底本資訊未錄')} · ${link(b.url,'查看來源全文')} · 每來源最多展示 8 處</p>${snippets.join('')}</article>`)}textResults=`<p class="result-caption">「${esc(q)}」在 ${books.length} 個完整轉錄來源中，共找到 ${total.toLocaleString()} 處。位置為此轉錄的字串位置，需核對源頁與底本。</p>`+results.join('')}catch(error){textResults='<div class="notice">全文未能完整載入，請重試；未載入不能視為沒有記載。</div>'}finally{if(run===textRun){textBusy=false;if(active==='corpus'&&document.querySelector('#fulltext-results')){document.querySelector('#fulltext-results').innerHTML=textResults;const b=document.querySelector('#search-fulltext');b.disabled=false;b.textContent='搜尋全文'}}}}
 function frameworkHTML(){return `<div class="notice">中醫分析有不同歷史體系，需依典籍、方證與時代選用。以下整理可追溯的分析框架；目前量化模型只編碼本草條目，未自動推導個人辨證或把各體系混成單一分數。</div><div class="framework-grid">${m.frameworks.map((f,i)=>`<article class="panel research-panel"><span class="eyebrow">${String(i+1).padStart(2,'0')} · ANALYTICAL FRAMEWORK</span><h2>${esc(f.title)}</h2><p>${esc(f.purpose)}</p><div class="tag-group">${f.dimensions.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><blockquote>${esc(f.quote)}</blockquote><p>${link(f.sourceUrl,'框架出處')}</p><p class="rule-note">${esc(f.limits)}</p></article>`).join('')}</div><section class="panel research-panel"><h2>從文獻描述走向可驗證模型</h2><p>目前已完成來源保存、保守擷取、公開編碼與程式一致性檢查。以下是研究驗證程序，尚未完成雙人標註、方族分組留出或藥理驗證。</p><ol class="protocol">${m.validationProtocol.map(x=>`<li>${esc(x.step)}</li>`).join('')}</ol></section>`+downloads()}
 function matchingQuant(){const q=quantQuery.trim().toLocaleLowerCase();return d.herbs.filter(h=>(!quantReview||(quantReview==='reviewed'?reviewed(h):!reviewed(h)))&&(!q||[h.name,h.nature,...h.effects||[]].join(' ').toLocaleLowerCase().includes(q)))}
 function quantRows(){const found=matchingQuant();return `<div class="table-scroll"><table class="research-table"><thead><tr><th>古籍條目</th><th>寒熱原詞 → 編碼</th><th>功用詞涵蓋</th><th>原文歸經</th><th>資料狀態</th></tr></thead><tbody>${found.slice(quantPage*30,(quantPage+1)*30).map(h=>{const t=Q.thermal(h,quantOptions.scheme,quantOptions.mild,quantOptions.strong);return `<tr><td><button class="text-button" data-detail="${esc(h.id)}">${esc(h.name)}</button><small>${sourceLink(h.sourceId)}</small></td><td>${esc(h.nature)}<small class="number-code">${range(t.range)}${t.status==='conditional'?'・加工／條件區間':''}</small>${t.range&&!t.evidence?.length?'<small>性原詞位置待補核</small>':''}</td><td>${Q.lexical(h).filter(x=>x.present).map(x=>`<span class="tag">${esc(x.label)}</span>`).join('')||'<span class="table-note">凍結詞典未命中；非無功用</span>'}</td><td>${esc(h.meridians?.join('、')||'未明載／未擷取')}</td><td>${badge(h)}<small>現代安全：未知</small></td></tr>`}).join('')}</tbody></table></div>${pager('quant',quantPage,found.length,30)}`}
 function profileHTML(r){return `<div class="profile-summary"><div><span>寒熱編碼區間</span><b>${range(r.range)}</b></div><div><span>性標籤涵蓋權重</span><b>${pct(r.thermalCoverage)}</b></div><div><span>寒側／溫側權重</span><b>${pct(r.totalWeight?r.negativeWeight/r.totalWeight:0)} / ${pct(r.totalWeight?r.positiveWeight/r.totalWeight:0)}</b></div></div>${r.unknownIds.length?`<div class="notice">${r.unknownIds.map(id=>esc(H(id).name)).join('、')} 的性資料未知；完整組合不給單一寒熱值。已知子集區間 ${range(r.knownSubsetRange)}，不能代表全方。</div>`:''}${r.unlinkedThermalIds?.length?`<p class="rule-note">${r.unlinkedThermalIds.map(id=>esc(H(id).name)).join('、')} 的性數值依既有節錄標籤，尚缺可核對的性原詞定位；禁止進入候選池。</p>`:''}${r.oppositeSigns?'<p class="rule-note">同時含寒側與溫側；平均接近 0 不表示原文性平或藥理作用抵銷。</p>':''}<div class="profile-bars">${r.labels.map(a=>`<div class="meridian-row"><span>${esc(a.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${pct(a.coverage)}"></div></div><small>${pct(a.coverage)}</small></div>`).join('')}</div><p class="rule-note">功用數值是所選權重中命中原詞的涵蓋比例（${esc(r.weightUnit||'研究份數')}），八軸可重疊、不可加總。未命中是詞典未覆蓋，不能判定沒有該作用。採用來源本草或所選炮製分支的屬性原詞；方名與方義不進入特徵。</p>`}
 function quantHTML(){const processing=context.processing?.({quantOptions});const r=processing?processing.quant:Q.aggregate(context.selection(),d,quantOptions);return `<div class="research-stats"><div><b>24 / 340</b><span>節錄人工核對</span></div><div><b>87</b><span>性資料未知</span></div><div><b>282</b><span>歸經未明載／未擷取</span></div><div><b>1,416</b><span>原文特徵定位片段</span></div></div><section class="panel research-panel"><h2>公開的文獻特性編碼</h2><p>基礎編碼：寒 −2、涼 −1、平 0、溫 1、熱 2。微／小乘倍率，大乘倍率；生熟或條件不明保留區間。這些是研究者設定的序位，沒有藥效單位。</p><div class="research-controls"><label>尺度<select id="quant-scheme"><option value="base" ${quantOptions.scheme==='base'?'selected':''}>基礎序位</option><option value="wide" ${quantOptions.scheme==='wide'?'selected':''}>極端詞加權：寒 −4／熱 4</option></select></label><label>微／小倍率<select id="quant-mild">${[.25,.5,.75].map(x=>`<option ${x===quantOptions.mild?'selected':''}>${x}</option>`).join('')}</select></label><label>大倍率<select id="quant-strong">${[1,1.5,2].map(x=>`<option ${x===quantOptions.strong?'selected':''}>${x}</option>`).join('')}</select></label></div><h3>當前工作台・${esc(context.name())}</h3><p class="rule-note">按工作台所選炮製分支及${processing?.basis==='grams'?'實錄克數':'研究份數'}計算。未載分支屬性保留未知；實錄工藝參數不產生藥效倍率。</p>${r?profileHTML(r):`<div class="notice">全方克數未完整，寒熱編碼與功用涵蓋保留未知。缺少：${processing.missingGrams.map(id=>esc(H(id).name)).join('、')}。請回工作台補齊，或選研究份數作文獻比較。</div>`}<details><summary>查看逐味特徵與原文依據</summary>${(r?.records||[]).map(x=>`<div class="record-evidence"><strong>${esc(x.name)}</strong> · ${range(x.thermal.range)} · ${badge(H(x.id))}<p>${x.terms.filter(t=>t.present).flatMap(t=>t.evidence.map(e=>`${esc(t.label)}：「${esc(e.text)}」`)).join('；')||'功用詞典未命中'}</p>${sourceLink(x.sourceId)}</div>`).join('')}</details></section><section class="panel research-panel"><h2>340 條特性矩陣</h2><div class="research-controls"><input class="search" id="quant-query" value="${esc(quantQuery)}" aria-label="搜尋特性矩陣" placeholder="草藥、寒熱或功用原詞"><select id="quant-review" aria-label="特性核對狀態"><option value="">所有狀態</option><option value="reviewed" ${quantReview==='reviewed'?'selected':''}>節錄已核 24 條</option><option value="automatic" ${quantReview==='automatic'?'selected':''}>自動擷取 316 條</option></select></div><div id="quant-rows">${quantRows()}</div></section>`+downloads()}
 function benchmarkHTML(){const f=F(benchmarkId),p=Q.referenceProfile(f,d),stats=Q.pairStats(pairA,pairB,d),ids=[...new Set(d.formulas.flatMap(f=>f.herbIds))];const choices=id=>ids.map(x=>`<option value="${x}" ${x===id?'selected':''}>${esc(H(x).name)}</option>`).join('');return `<div class="notice">先描述已有方的原文結構，再與獨立方義作詞語核對。18 方中僅 4 方已有方義來源片段；凍結詞典能映射的範圍更小。這一步尚未完成獨立留出驗證，不能稱為藥性或療效預測。</div><section class="panel research-panel"><div class="panel-heading"><h2>經方文獻輪廓</h2><select id="benchmark-formula" aria-label="選擇分析經方">${d.formulas.map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="benchmark-grid"><div><h3>${esc(f.name)}</h3><p>${esc(f.ingredientSummary)}</p><p>${esc(f.note)}</p><p>${sourceLink(f.sourceId,'成分原文')}</p><button class="button secondary" data-stage-formula="${f.id}">載入配伍工作台</button>${p.unresolved.length||p.ambiguous?.length?`<div class="notice">身份／解析待核：${[...p.unresolved,...p.ambiguous||[]].map(x=>esc(x.sourceName)).join('、')}。只描述已解析子集，完整方的寒熱編碼為未知；此方排除於藥對頻數樣本。</div>`:''}<h3>方義來源片段</h3>${f.profileEvidence?.length?f.profileEvidence.map(e=>`<blockquote>${esc(e.text)}</blockquote><p>${sourceLink(e.sourceId)}</p>`).join(''):'<p class="table-note">尚缺方義來源片段；不以本草特徵反填標準答案。</p>'}<p class="rule-note">${esc(p.status)}。${p.expected.length?`方義原詞命中 ${p.expected.map(id=>esc(Q.axes.find(a=>a.id===id).label)).join('、')}；本草輸入同詞覆蓋 ${p.overlapping.length} / ${p.expected.length}。`:'獨立片段沒有凍結詞典可映射詞，核對值為未評估。'} 此處只核對文字，不核對人體藥效。</p></div><div>${profileHTML(p.result)}</div></div></section><section class="panel research-panel"><h2>藥對同現・完整 2×2 頻數</h2><div class="research-controls"><select id="pair-a" aria-label="藥對第一味">${choices(pairA)}</select><span>×</span><select id="pair-b" aria-label="藥對第二味">${choices(pairB)}</select></div><div class="pair-grid"><div class="pair-table"><span></span><span>${esc(H(pairB).name)} 有</span><span>${esc(H(pairB).name)} 無</span><span>${esc(H(pairA).name)} 有</span><b>${stats.n11}</b><b>${stats.n10}</b><span>${esc(H(pairA).name)} 無</span><b>${stats.n01}</b><b>${stats.n00}</b></div><div><h3>${esc(stats.status)}</h3><p>分母 N = ${stats.N} 個成分完整、去除相同成分集合的方劑；兩味皆無也計入。${stats.excluded.length} 方因核心名稱映射／解析未完成被排除。</p><p>φ：${stats.phi===null?'未估計':number(stats.phi)}　log lift：${stats.logLift===null?'未估計':number(stats.logLift)}</p><p class="rule-note">至少 N≥30、共同出現≥3、各有／無邊際≥3 才顯示描述性關聯；估計時四格均加 0.5。現有樣本不足，不能排名為協同強度，亦未完成方族獨立性校訂。</p><p>共同出現：${stats.examples.map(id=>esc(F(id).name)).join('、')||'此語料未出現'}</p></div></div></section><section class="panel research-panel"><h2>18 方資料完整度</h2><div class="table-scroll"><table class="research-table"><thead><tr><th>方劑</th><th>成分身份</th><th>方義來源片段</th><th>模型驗證</th></tr></thead><tbody>${d.formulas.map(x=>{const z=Q.referenceProfile(x,d);return `<tr><td><button class="text-button" data-benchmark="${x.id}">${esc(x.name)}</button></td><td>${x.herbIds.length} 已解析${z.unresolved.length||z.ambiguous?.length?`／${z.unresolved.length+(z.ambiguous?.length||0)} 待核`:''}</td><td>${x.profileEvidence?.length?'有來源片段':'尚缺'}</td><td>獨立留出未完成</td></tr>`}).join('')}</tbody></table></div></section>`}
 function discoveryHTML(){return `<div class="notice">產出待審的文獻組合假設。排序分只表示公開設定下的詞語、寒熱編碼與已收錄成分重疊，不能當作療效、協同或安全分數；「新」僅相對此處身份完整的經方語料；身份待核方不作新穎性證據。</div><section class="panel research-panel"><h2>有約束的組合探索</h2><div class="research-controls discovery-controls"><label>文獻目標詞<select id="discovery-goal">${Q.axes.map(a=>`<option value="${a.id}" ${(discoveryResult?.config.goal??'blood')===a.id?'selected':''}>${esc(a.label)}</option>`).join('')}</select></label><label>寒熱編碼中心<select id="discovery-target">${[-1,0,1].map(x=>`<option value="${x}" ${(discoveryResult?.config.target??1)===x?'selected':''}>${x}（${x<0?'偏寒側':x>0?'偏溫側':'編碼中心'}）</option>`).join('')}</select></label><label>條目數<select id="discovery-size">${[3,4,5].map(x=>`<option ${(discoveryResult?.config.size??3)===x?'selected':''}>${x}</option>`).join('')}</select></label><label>新穎性排序權重<select id="discovery-novelty">${[0,.25,.5,.75,1].map(x=>`<option ${(discoveryResult?.config.noveltyWeight??.25)===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="button primary" id="generate-hypotheses">探索文獻組合</button></div><details><summary>查看資格約束與排序假設</summary><p>只從已錄經方涉及、節錄已核且有性資料與原文定位的條目選取；排除毒性提示、加工性味未定、名稱歧義與已錄配伍警示。當前候選池 ${Q.candidatePool(d).length} 條，未完成現代基原及安全核定。各條等权 1，不產生服用比例。</p><p>排序 = (1−新穎權重)×(0.7×目標詞涵蓋＋0.3×寒熱編碼接近度)＋新穎權重×(1−最高成分重疊)。接近度 = 1−min(1, |編碼區間中點−目標|/s)，基礎尺度 s=3，極端詞尺度 s=6。係數為公開研究假設，未由臨床資料學得。四組設定是（基礎、0.5、1.5）、（極端詞、0.5、1.5）、（基礎、0.25、1）與（基礎、0.75、2），依次為尺度、微倍率、大倍率；返回最多五個成分互異的候選。候選池很小，部分目標或條目數會沒有結果。</p></details><div id="discovery-results">${discoveryResult?discoveryResultsHTML():'<div class="empty-state">選取文獻探索條件，即可生成有出處的待審候選。</div>'}</div></section>`+downloads()}
 function discoveryResultsHTML(){const r=discoveryResult;return `<div class="generation-summary"><b>${r.considered} 個組合已檢視</b><span>${r.matchingCount} 個符合詞語條件</span><span>${r.rejectedRules} 個命中已錄提示</span><button class="button secondary" id="export-hypotheses">匯出假設與參數</button></div>${r.results.length?`<div class="candidate-grid">${r.results.map((x,i)=>`<article class="candidate-card"><span class="eyebrow">HYPOTHESIS ${String(i+1).padStart(2,'0')}</span><h3>${x.rows.map(row=>esc(H(row.id).name)).join('・')}</h3><span class="review-tag">待審文獻組合假設</span><div class="candidate-metrics"><div><span>排序分（假設）</span><b>${number(x.score)}</b></div><div><span>目標詞涵蓋</span><b>${pct(x.goalCoverage)}</b></div><div><span>寒熱編碼</span><b>${range(x.profile.range)}</b></div></div><p>最接近身份完整的已錄方：${esc(F(x.nearest.id).name)}（成分重疊 ${pct(x.nearest.value)}）；相對新穎性 ${pct(x.novelty)}。</p><p class="sensitivity">四種編碼下的排名：${x.rankRange.join(' ～ ')} · ${x.sensitivityStable?'排名未變':'對假設敏感'}</p><details><summary>本草原詞與來源</summary>${x.rows.map(row=>{const h=H(row.id);return `<p><strong>${esc(h.name)}</strong> · ${esc(h.nature)}<br>${esc((h.effects||[]).join('、'))}<br>${sourceLink(h.sourceId)}</p>`}).join('')}</details><p class="rule-note">${esc(x.modernIdentity)}。本候選未經實驗或臨床驗證。</p><button class="button secondary" data-stage-candidate="${i}">送至文獻工作台</button></article>`).join('')}</div>`:'<p class="empty-state">目前有限的校核候選池沒有符合組合。可調整文獻目標或條目數；不以未知條目補滿結果。</p>'}<p class="rule-note">每味權重固定 1，僅供文獻比較。候選不存在於已錄方，不證明歷史上從未出現。生成結果通過的只是有限文獻條件。</p>`}
 function downloadJSON(value,filename){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 document.addEventListener('input',e=>{if(e.target.id==='corpus-query'){corpusQuery=e.target.value;corpusPage=0;document.querySelector('#book-rows').innerHTML=bookRows()}if(e.target.id==='quant-query'){quantQuery=e.target.value;quantPage=0;document.querySelector('#quant-rows').innerHTML=quantRows()}});
 document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='corpus-category'||id==='corpus-status'){if(id==='corpus-category')category=v;else corpusStatus=v;corpusPage=0;document.querySelector('#book-rows').innerHTML=bookRows()}if(id==='quant-review'){quantReview=v;quantPage=0;document.querySelector('#quant-rows').innerHTML=quantRows()}if(['quant-scheme','quant-mild','quant-strong'].includes(id)){quantOptions[id.split('-')[1]]=id==='quant-scheme'?v:Number(v);render('quant',context)}if(id==='benchmark-formula'){benchmarkId=v;render('benchmark',context)}if(id==='pair-a'||id==='pair-b'){const other=id==='pair-a'?pairB:pairA;if(v===other){context.notify('請選兩個不同條目');e.target.value=id==='pair-a'?pairA:pairB;return}if(id==='pair-a')pairA=v;else pairB=v;render('benchmark',context)}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.researchPage){if(b.dataset.researchPage==='corpus'){corpusPage+=Number(b.dataset.delta);document.querySelector('#book-rows').innerHTML=bookRows()}else{quantPage+=Number(b.dataset.delta);document.querySelector('#quant-rows').innerHTML=quantRows()}return}if(b.id==='search-fulltext')searchText();if(b.dataset.benchmark){benchmarkId=b.dataset.benchmark;render('benchmark',context);window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.stageFormula)context.loadFormula(b.dataset.stageFormula);if(b.id==='generate-hypotheses'){try{discoveryResult=Q.generate(d,{goal:document.querySelector('#discovery-goal').value,target:Number(document.querySelector('#discovery-target').value),size:Number(document.querySelector('#discovery-size').value),noveltyWeight:Number(document.querySelector('#discovery-novelty').value)});document.querySelector('#discovery-results').innerHTML=discoveryResultsHTML()}catch(error){context.notify(error.message)}}if(b.dataset.stageCandidate!==undefined){const x=discoveryResult?.results[Number(b.dataset.stageCandidate)];if(x)context.stage(x.rows,'待審文獻組合假設 '+(Number(b.dataset.stageCandidate)+1))}if(b.id==='export-hypotheses'&&discoveryResult){downloadJSON({...discoveryResult,createdAt:new Date().toISOString(),purpose:'文獻組合假設；非可服用處方',sources:d.sources.filter(s=>discoveryResult.results.some(x=>x.rows.some(row=>H(row.id).sourceId===s.id)))},'本草文獻組合假設.json');context.notify('已匯出候選、來源與完整排序參數')}});
 return {render,badge,downloads};
})();
